// Fixed 2026-08-23: previously a Merge node with mode 'chooseBranch'
// and output hardcoded to 'input1' -- meaning it ALWAYS returned the
// Media branch's item and silently dropped every plain text message,
// since only one of the two upstream branches ever actually executes.
// Using $(name).isExecuted instead, matching the same safe pattern
// already used in voxitron-kb-ingest's 'Merge Content Sources' node.
//
// pairedItem is required here -- without it, downstream nodes using
// $('Merge Message Text').item.json... (Log Inbound Message, AI Agent
// Reply, Send WhatsApp Reply) can't resolve which item this corresponds
// to and throw 'Paired item data ... is unavailable'.
const candidates = [
  'Resolve Message Text (Text)',
  'Resolve Message Text (Media)',
];

for (const name of candidates) {
  if ($(name).isExecuted) {
    return [{
      json: { messageText: $(name).item.json.messageText },
      pairedItem: { item: 0 }
    }];
  }
}

throw new Error('Merge Message Text: neither Resolve Message Text branch executed, this should be unreachable.');

const calendarId = $('Load Customer by Number').item.json.calendar_id;

if (!calendarId) {
  return 'No calendar connected for this business.';
}

try {
  const timeMin = new Date().toISOString();
  const timeMax = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleCalendarOAuth2Api',
    {
      method: 'POST',
      url: 'https://www.googleapis.com/calendar/v3/freeBusy',
      body: { timeMin, timeMax, items: [{ id: calendarId }] },
      json: true,
    }
  );

  const busy = response.calendars?.[calendarId]?.busy || [];
  if (busy.length === 0) {
    return 'Open across the next 7 days, no busy periods found.';
  }

  const busyText = busy.slice(0, 10)
    .map(b => `${b.start} to ${b.end}`)
    .join(', ');
  return `Busy during: ${busyText}. Anything outside these windows is free.`;

} catch (error) {
  return 'Having trouble checking the calendar right now.';
}

const searchTerm = ($fromAI('searchTerm', 'the product name or keyword the customer mentioned', 'string') || '').toLowerCase().trim();

if (!searchTerm) {
  return 'No search term provided.';
}

try {
  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'GET',
      url: 'https://sheets.googleapis.com/v4/spreadsheets/CONNECT_YOUR_SHEET_ID/values/A:Z',
      json: true,
    }
  );

  const rows = response.values || [];
  if (rows.length < 2) {
    return 'The sheet is empty or has no data rows.';
  }

  const headers = rows[0];
  const dataRows = rows.slice(1);

  const matches = dataRows.filter(row =>
    row.some(cell => (cell || '').toString().toLowerCase().includes(searchTerm))
  );

  if (matches.length === 0) {
    return `Nothing matching "${searchTerm}" was found in the sheet.`;
  }

  const formatted = matches.slice(0, 10).map(row =>
    headers.map((h, i) => `${h}: ${row[i] || ''}`).join(' | ')
  ).join('\n');

  return formatted;

} catch (error) {
  // Graceful failure -- the agent gets a clean sentence to relay,
  // never a stack trace, never a guessed answer.
  return 'Having trouble checking the live sheet right now, cannot confirm this from there at the moment.';
}

